// Geo: the world map and IP geolocation used by the Network Map. The map is a compact land/sea bitmask
// (234x117, ~3.4 KB) baked into the code and drawn as a dot grid, so nothing is downloaded to show the world.
// Geolocation of the IPs this machine talks to uses ip-api.com's free batch endpoint (opt-in: this is the one
// tool that sends the remote IPs to a third party), cached to disk so a repeat lookup is instant and offline.
using System;
using System.Collections.Generic;
using System.Drawing;
using System.IO;
using System.Net;
using System.Text;

namespace PSTools
{
    /// <summary>The world as a 600x300 grid of country indexes (0 = ocean), rasterized from Natural Earth's 110m
    /// country polygons and RLE-packed into ~19 KB, so the map, its coastlines, every country's shape and name all ship
    /// inside the exe with nothing downloaded.</summary>
    public static class WorldMap
    {
        public const int W = 600, H = 300;
        static byte[] country; static List<int>[] cells; static readonly object gate = new object();
        static readonly string[] Names = { "Fiji", "Tanzania", "W. Sahara", "Canada", "United States of America", "Kazakhstan", "Uzbekistan", "Papua New Guinea", "Indonesia", "Argentina", "Chile", "Dem. Rep. Congo", "Somalia", "Kenya", "Sudan", "Chad", "Haiti", "Dominican Rep.", "Russia", "Bahamas", "Falkland Is.", "Norway", "Greenland", "Fr. S. Antarctic Lands", "Timor-Leste", "South Africa", "Lesotho", "Mexico", "Uruguay", "Brazil", "Bolivia", "Peru", "Colombia", "Panama", "Costa Rica", "Nicaragua", "Honduras", "El Salvador", "Guatemala", "Belize", "Venezuela", "Guyana", "Suriname", "France", "Ecuador", "Puerto Rico", "Jamaica", "Cuba", "Zimbabwe", "Botswana", "Namibia", "Senegal", "Mali", "Mauritania", "Benin", "Niger", "Nigeria", "Cameroon", "Togo", "Ghana", "Côte d'Ivoire", "Guinea", "Guinea-Bissau", "Liberia", "Sierra Leone", "Burkina Faso", "Central African Rep.", "Congo", "Gabon", "Eq. Guinea", "Zambia", "Malawi", "Mozambique", "eSwatini", "Angola", "Burundi", "Israel", "Lebanon", "Madagascar", "Palestine", "Gambia", "Tunisia", "Algeria", "Jordan", "United Arab Emirates", "Qatar", "Kuwait", "Iraq", "Oman", "Vanuatu", "Cambodia", "Thailand", "Laos", "Myanmar", "Vietnam", "North Korea", "South Korea", "Mongolia", "India", "Bangladesh", "Bhutan", "Nepal", "Pakistan", "Afghanistan", "Tajikistan", "Kyrgyzstan", "Turkmenistan", "Iran", "Syria", "Armenia", "Sweden", "Belarus", "Ukraine", "Poland", "Austria", "Hungary", "Moldova", "Romania", "Lithuania", "Latvia", "Estonia", "Germany", "Bulgaria", "Greece", "Turkey", "Albania", "Croatia", "Switzerland", "Luxembourg", "Belgium", "Netherlands", "Portugal", "Spain", "Ireland", "New Caledonia", "Solomon Is.", "New Zealand", "Australia", "Sri Lanka", "China", "Taiwan", "Italy", "Denmark", "United Kingdom", "Iceland", "Azerbaijan", "Georgia", "Philippines", "Malaysia", "Brunei", "Slovenia", "Finland", "Slovakia", "Czechia", "Eritrea", "Japan", "Paraguay", "Yemen", "Saudi Arabia", "Antarctica", "N. Cyprus", "Cyprus", "Morocco", "Egypt", "Libya", "Ethiopia", "Djibouti", "Somaliland", "Uganda", "Rwanda", "Bosnia and Herz.", "North Macedonia", "Serbia", "Montenegro", "Kosovo", "Trinidad and Tobago", "S. Sudan" };
        const string Rle = "";
        static void Ensure()
        {
            if (country != null) return;
            lock (gate)
            {
                if (country != null) return;
                byte[] r = Convert.FromBase64String(Rle); byte[] g = new byte[W * H]; int i = 0, o = 0;
                while (i + 2 < r.Length && o < g.Length) { byte v = r[i]; int n = r[i + 1] | (r[i + 2] << 8); i += 3; for (int k = 0; k < n && o < g.Length; k++) g[o++] = v; }
                country = g;
            }
        }
        public static int Country(int gx, int gy) { Ensure(); if (gx < 0 || gx >= W || gy < 0 || gy >= H) return 0; return country[gy * W + gx]; }
        public static bool Land(int gx, int gy) { return Country(gx, gy) > 0; }
        public static string Name(int id) { return id > 0 && id <= Names.Length ? Names[id - 1] : ""; }
        public static int CountryCount { get { return Names.Length; } }
        /// <summary>True when a 4-neighbour is a different country (not ocean): an internal border cell.</summary>
        public static bool Border(int gx, int gy) { int c = Country(gx, gy); if (c == 0) return false; int l = Country(gx - 1, gy), r = Country(gx + 1, gy), u = Country(gx, gy - 1), d = Country(gx, gy + 1); return (l != 0 && l != c) || (r != 0 && r != c) || (u != 0 && u != c) || (d != 0 && d != c); }
        /// <summary>True when a 4-neighbour is ocean: a coastline cell.</summary>
        public static bool Coast(int gx, int gy) { if (Country(gx, gy) == 0) return false; return Country(gx - 1, gy) == 0 || Country(gx + 1, gy) == 0 || Country(gx, gy - 1) == 0 || Country(gx, gy + 1) == 0; }
        /// <summary>Every cell index (gy*W+gx) of one country, for highlighting its whole shape.</summary>
        public static List<int> CellsOf(int id)
        {
            Ensure();
            lock (gate)
            {
                if (cells == null) { cells = new List<int>[Names.Length + 1]; for (int i = 0; i < country.Length; i++) { int c = country[i]; if (c == 0) continue; if (cells[c] == null) cells[c] = new List<int>(); cells[c].Add(i); } }
            }
            return id > 0 && id < cells.Length && cells[id] != null ? cells[id] : new List<int>();
        }
        /// <summary>lat/lon -> normalized (u,v) in [0,1] on an equirectangular map (u=0 at 180W, v=0 at 90N).</summary>
        public static PointF Norm(double lat, double lon) { double u = (lon + 180.0) / 360.0; double v = (90.0 - lat) / 180.0; return new PointF((float)u, (float)v); }
    }

    public class GeoLoc
    {
        public double Lat, Lon; public string Country = "", CountryCode = "", City = "", Query = "", Isp = ""; public bool Ok;
        public string Place { get { return City.Length > 0 ? City + ", " + Country : Country; } }
    }

    public static class GeoIp
    {
        static readonly Dictionary<string, GeoLoc> cache = new Dictionary<string, GeoLoc>(StringComparer.OrdinalIgnoreCase);
        static string cacheFile; static bool loaded;

        public static bool IsPublic(string ip)
        {
            if (string.IsNullOrEmpty(ip)) return false; IPAddress a; if (!IPAddress.TryParse(ip, out a)) return false;
            if (IPAddress.IsLoopback(a)) return false;
            byte[] b = a.GetAddressBytes();
            if (b.Length == 4)
            {
                if (b[0] == 10) return false; if (b[0] == 127) return false; if (b[0] == 169 && b[1] == 254) return false;
                if (b[0] == 172 && b[1] >= 16 && b[1] <= 31) return false; if (b[0] == 192 && b[1] == 168) return false;
                if (b[0] == 100 && b[1] >= 64 && b[1] <= 127) return false; // CGNAT
                if (b[0] == 0 || b[0] >= 224) return false; // this-net, multicast, reserved
                return true;
            }
            if (b.Length == 16) { if (b[0] == 0xfe && (b[1] & 0xc0) == 0x80) return false; if ((b[0] & 0xfe) == 0xfc) return false; bool allZeroBut1 = true; for (int i = 0; i < 15; i++) if (b[i] != 0) allZeroBut1 = false; if (allZeroBut1) return false; return true; }
            return false;
        }

        static void Load()
        {
            if (loaded) return; loaded = true;
            try
            {
                string dir = Path.Combine(Path.GetDirectoryName(System.Windows.Forms.Application.ExecutablePath), "cache"); Directory.CreateDirectory(dir); cacheFile = Path.Combine(dir, "geoip.json");
                if (File.Exists(cacheFile)) { object doc = Json.Parse(File.ReadAllText(cacheFile)); foreach (object o in Json.Arr(doc)) { GeoLoc g = new GeoLoc(); g.Query = Json.GetS(o, "q") ?? ""; g.Lat = N(Json.Get(o, "lat")); g.Lon = N(Json.Get(o, "lon")); g.Country = Json.GetS(o, "country") ?? ""; g.CountryCode = Json.GetS(o, "cc") ?? ""; g.City = Json.GetS(o, "city") ?? ""; g.Isp = Json.GetS(o, "isp") ?? ""; g.Ok = true; if (g.Query.Length > 0) cache[g.Query] = g; } }
            }
            catch { }
        }
        static double N(object o) { double? d = Json.N(o); return d.HasValue ? d.Value : 0; }
        static void Save()
        {
            try { if (cacheFile == null) return; StringBuilder sb = new StringBuilder("["); bool first = true; lock (cache) foreach (GeoLoc g in cache.Values) { if (!g.Ok) continue; if (!first) sb.Append(","); first = false; sb.Append("{\"q\":").Append(Json.Quote(g.Query)).Append(",\"lat\":").Append(g.Lat.ToString(System.Globalization.CultureInfo.InvariantCulture)).Append(",\"lon\":").Append(g.Lon.ToString(System.Globalization.CultureInfo.InvariantCulture)).Append(",\"country\":").Append(Json.Quote(g.Country)).Append(",\"cc\":").Append(Json.Quote(g.CountryCode)).Append(",\"city\":").Append(Json.Quote(g.City)).Append(",\"isp\":").Append(Json.Quote(g.Isp)).Append("}"); } sb.Append("]"); File.WriteAllText(cacheFile, sb.ToString()); }
            catch { }
        }

        public static GeoLoc Cached(string ip) { Load(); GeoLoc g; lock (cache) return cache.TryGetValue(ip, out g) ? g : null; }

        /// <summary>Geolocate the given public IPs (batched, cached). progress(done,total). Returns only successful ones.</summary>
        public static Dictionary<string, GeoLoc> Locate(IEnumerable<string> ips, Action<int, int> progress)
        {
            Load(); List<string> todo = new List<string>(); HashSet<string> seen = new HashSet<string>();
            foreach (string ip in ips) { if (!IsPublic(ip) || !seen.Add(ip)) continue; lock (cache) { if (cache.ContainsKey(ip)) continue; } todo.Add(ip); }
            int total = todo.Count, done = 0;
            for (int i = 0; i < todo.Count; i += 100)
            {
                List<string> batch = todo.GetRange(i, Math.Min(100, todo.Count - i));
                try { BatchLookup(batch); } catch { }
                done += batch.Count; if (progress != null) progress(done, total);
                if (i + 100 < todo.Count) System.Threading.Thread.Sleep(1500); // ip-api free: ~15 batch req/min
            }
            if (total > 0) Save();
            Dictionary<string, GeoLoc> outp = new Dictionary<string, GeoLoc>(StringComparer.OrdinalIgnoreCase);
            foreach (string ip in seen) { GeoLoc g = Cached(ip); if (g != null && g.Ok) outp[ip] = g; }
            return outp;
        }
        static void BatchLookup(List<string> ips)
        {
            StringBuilder body = new StringBuilder("["); for (int i = 0; i < ips.Count; i++) { if (i > 0) body.Append(","); body.Append(Json.Quote(ips[i])); } body.Append("]");
            string resp = Post("http://ip-api.com/batch?fields=status,country,countryCode,city,lat,lon,query,isp", body.ToString(), 15000);
            object arr = Json.Parse(resp);
            foreach (object o in Json.Arr(arr))
            {
                GeoLoc g = new GeoLoc(); g.Query = Json.GetS(o, "query") ?? ""; g.Ok = (Json.GetS(o, "status") ?? "") == "success";
                if (g.Ok) { g.Lat = N(Json.Get(o, "lat")); g.Lon = N(Json.Get(o, "lon")); g.Country = Json.GetS(o, "country") ?? ""; g.CountryCode = Json.GetS(o, "countryCode") ?? ""; g.City = Json.GetS(o, "city") ?? ""; g.Isp = Json.GetS(o, "isp") ?? ""; }
                if (g.Query.Length > 0 && g.Ok) lock (cache) cache[g.Query] = g;
            }
        }
        /// <summary>This machine's own public location (ip-api resolves the caller's IP when none is given).</summary>
        public static GeoLoc Mine()
        {
            try
            {
                string resp = Http.Get("http://ip-api.com/json/?fields=status,country,countryCode,city,lat,lon,query,isp");
                object o = Json.Parse(resp); GeoLoc g = new GeoLoc(); g.Ok = (Json.GetS(o, "status") ?? "") == "success";
                if (g.Ok) { g.Query = Json.GetS(o, "query") ?? ""; g.Lat = N(Json.Get(o, "lat")); g.Lon = N(Json.Get(o, "lon")); g.Country = Json.GetS(o, "country") ?? ""; g.CountryCode = Json.GetS(o, "countryCode") ?? ""; g.City = Json.GetS(o, "city") ?? ""; g.Isp = Json.GetS(o, "isp") ?? ""; if (g.Query.Length > 0) lock (cache) cache[g.Query] = g; }
                return g;
            }
            catch { return new GeoLoc(); }
        }
        static string Post(string url, string body, int timeoutMs)
        {
            HttpWebRequest r = (HttpWebRequest)WebRequest.Create(url); r.Method = "POST"; r.ContentType = "application/json"; r.Timeout = timeoutMs; r.ReadWriteTimeout = timeoutMs; r.UserAgent = "PowerTower";
            byte[] data = Encoding.UTF8.GetBytes(body); r.ContentLength = data.Length;
            using (Stream s = r.GetRequestStream()) s.Write(data, 0, data.Length);
            using (HttpWebResponse resp = (HttpWebResponse)r.GetResponse()) using (StreamReader sr = new StreamReader(resp.GetResponseStream())) return sr.ReadToEnd();
        }
    }
}
